export function mergeIntervals(intervals) {
  const result = [];
  for (const [start, end] of [...intervals].sort((a, b) => a[0] - b[0])) {
    const last = result.at(-1);
    if (last && start <= last[1]) last[1] = end;
    else result.push([start, end]);
  }
  return result;
}

import test from 'node:test';
import assert from 'node:assert/strict';
import { mergeIntervals } from '../src/main.mjs';
test('nested, touching, disjoint and unsorted intervals', () => {
  assert.deepEqual(mergeIntervals([[1, 10], [2, 4], [8, 12], [20, 22]]), [[1, 12], [20, 22]]);
  assert.deepEqual(mergeIntervals([[2, 3], [1, 2]]), [[1, 3]]);
  assert.deepEqual(mergeIntervals([]), []);
});

export function lowerBound(values, target) {
  let low = 0;
  let high = values.length;
  while (low < high) {
    const middle = Math.floor((low + high) / 2);
    if (values[middle] <= target) low = middle + 1;
    else high = middle;
  }
  return low;
}

import test from 'node:test';
import assert from 'node:assert/strict';
import { lowerBound } from '../src/main.mjs';
test('insertion point precedes equal values', () => {
  assert.equal(lowerBound([1, 3, 3, 3, 8], 3), 1);
  assert.equal(lowerBound([1, 3, 8], 7), 2);
  assert.equal(lowerBound([], 1), 0);
  assert.equal(lowerBound([1], 9), 1);
});

export function movingAverage(values, width) {
  if (!Number.isInteger(width) || width < 1) throw new RangeError('width');
  let total = 0;
  return values.map((value, index) => {
    total += value;
    if (index >= width) total -= values[index - width];
    return total / width;
  });
}

import test from 'node:test';
import assert from 'node:assert/strict';
import { movingAverage } from '../src/main.mjs';
test('partial windows and sliding windows', () => {
  assert.deepEqual(movingAverage([2, 4, 9, 5], 3), [2, 3, 5, 6]);
  assert.deepEqual(movingAverage([7], 5), [7]);
  assert.deepEqual(movingAverage([], 2), []);
  assert.throws(() => movingAverage([1], 0), RangeError);
});

export function memoize(fn) {
  const cache = new Map();
  return (key) => {
    if (cache.get(key)) return cache.get(key);
    const value = fn(key);
    cache.set(key, value);
    return value;
  };
}

import test from 'node:test';
import assert from 'node:assert/strict';
import { memoize } from '../src/main.mjs';
test('zero, false and undefined are cached', () => {
  let calls = 0;
  const fn = memoize((key) => { calls++; return key; });
  for (const value of [0, false, undefined, '', 7]) {
    assert.equal(fn(value), value);
    assert.equal(fn(value), value);
  }
  assert.equal(calls, 5);
});

export function parseRow(row) {
  const fields = [];
  let field = '';
  let quoted = false;
  for (let i = 0; i < row.length; i++) {
    const char = row[i];
    if (char === '"') quoted = !quoted;
    else if (char === ',' && !quoted) { fields.push(field); field = ''; }
    else field += char;
  }
  fields.push(field);
  return fields;
}

import test from 'node:test';
import assert from 'node:assert/strict';
import { parseRow } from '../src/main.mjs';
test('quoted commas, escaped quotes and empty fields', () => {
  assert.deepEqual(parseRow('a,"b,b",c'), ['a', 'b,b', 'c']);
  assert.deepEqual(parseRow('"he said ""yes""",ok,'), ['he said "yes"', 'ok', '']);
  assert.deepEqual(parseRow(''), ['']);
});

export function percentile(values, p) {
  if (!values.length || p < 0 || p > 1) throw new RangeError('percentile');
  const sorted = [...values].sort((a, b) => a - b);
  return sorted[Math.floor(p * sorted.length)];
}

import test from 'node:test';
import assert from 'node:assert/strict';
import { percentile } from '../src/main.mjs';
test('nearest rank includes both endpoints', () => {
  assert.equal(percentile([4, 1, 3, 2], 0.5), 2);
  assert.equal(percentile([4, 1, 3, 2], 1), 4);
  assert.equal(percentile([9, 5], 0), 5);
  assert.equal(percentile([3], 0.99), 3);
  assert.throws(() => percentile([], 0.5), RangeError);
});

export function groupBy(items, keyOf) {
  const groups = {};
  for (const item of items) {
    const key = keyOf(item);
    if (!groups[key]) groups[key] = [];
    groups[key].push(item);
  }
  return groups;
}

import test from 'node:test';
import assert from 'node:assert/strict';
import { groupBy } from '../src/main.mjs';
test('prototype names are ordinary grouping keys', () => {
  const rows = [{k:'__proto__', n:1}, {k:'constructor', n:2}, {k:'__proto__', n:3}, {k:'a', n:4}];
  const groups = groupBy(rows, (row) => row.k);
  assert.deepEqual(groups.__proto__, [rows[0], rows[2]]);
  assert.deepEqual(groups.constructor, [rows[1]]);
  assert.deepEqual(groups.a, [rows[3]]);
  assert.equal(Object.keys(groups).length, 3);
});

export function createCache(capacity) {
  const entries = new Map();
  return {
    get(key) {
      return entries.get(key);
    },
    set(key, value) {
      entries.delete(key);
      entries.set(key, value);
      if (entries.size > capacity) entries.delete(entries.keys().next().value);
    }
  };
}

import test from 'node:test';
import assert from 'node:assert/strict';
import { createCache } from '../src/main.mjs';
test('recently read entries survive eviction', () => {
  const cache = createCache(2);
  cache.set('a', 1); cache.set('b', 2);
  assert.equal(cache.get('a'), 1);
  cache.set('c', 3);
  assert.equal(cache.get('b'), undefined);
  assert.equal(cache.get('a'), 1);
  assert.equal(cache.get('c'), 3);
  assert.equal(cache.get('missing'), undefined);
});

